// One time step for N neurons; fixed-point Q8.8, leak by shift (decay = 1 - 1/16)
void lif_step(short v[N], const short i_syn[N], bool spike[N]) {
#pragma HLS PIPELINE II=1
  for (int n = 0; n < N; n++) {
    short vn = v[n] - (v[n] >> 4) + i_syn[n];   // leak + input
    bool s = vn >= V_TH;
    spike[n] = s;
    v[n] = s ? V_RESET : vn;
  }
}
